package com.singtel.eligibilityservice;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.client.RestClient;import org.springframework.beans.factory.annotation.Value;import java.util.*;import java.time.Instant;import com.singtel.platformcommon.DomainError;
@RestController @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public class EligibilityController{private final RestClient client;private final String customerUrl,promotionUrl,ruleUrl;public EligibilityController(RestClient c,@Value("${platform.customer-url}")String u,@Value("${platform.promotion-url}")String p,@Value("${platform.rule-url}")String r){client=c;customerUrl=u;promotionUrl=p;ruleUrl=r;}
 @GetMapping("/api/v1/customers/{id}/eligible-promotions")public List<Map<String,Object>> offers(@PathVariable String id){Map<String,Object> facts=client.get().uri(customerUrl+"/api/v1/customers/"+id).retrieve().body(Map.class);List<Map<String,Object>> promotions=client.get().uri(promotionUrl+"/api/v1/promotions?size=100").retrieve().body(List.class);return promotions.stream().filter(p->"ACTIVE".equals(p.get("status"))).map(p->decision(p,facts)).toList();}
 @GetMapping("/api/v1/eligibility/{customerId}/{promotionId}")public Map<String,Object> eligibility(@PathVariable String customerId,@PathVariable UUID promotionId){Map<String,Object> facts=client.get().uri(customerUrl+"/api/v1/customers/"+customerId).retrieve().body(Map.class);Map<String,Object> p=client.get().uri(promotionUrl+"/api/v1/promotions/"+promotionId).retrieve().body(Map.class);return decision(p,facts);}
 private Map<String,Object> decision(Map<String,Object> p,Map<String,Object> facts){Map<String,Object> result=client.post().uri(ruleUrl+"/api/v1/rules/"+p.get("ruleVersionId")+"/evaluate").body(facts).retrieve().body(Map.class);List<String> reasons=new ArrayList<>((List<String>)result.get("reasons"));Instant now=Instant.now();boolean valid="ACTIVE".equals(p.get("status"))&&"ACTIVE".equals(facts.get("status"))&&!now.isBefore(Instant.parse((String)p.get("startAt")))&&now.isBefore(Instant.parse((String)p.get("endAt")));if(!valid)reasons.add("Failed: campaign validity or customer status");return Map.of("promotion",p,"customer",facts,"eligible",valid&&Boolean.TRUE.equals(result.get("eligible")),"reasons",reasons);}
}
